<?php require "db.php";require_role("admin");if($_SERVER["REQUEST_METHOD"]==="POST"){$d=input();if(($d["action"]??"")==="delete_job"){$s=$pdo->prepare("DELETE FROM jobs WHERE id=?");$s->execute([(int)($d["id"]??0)]);done(["success"=>true,"message"=>"Job removed."]);}done(["success"=>false,"message"=>"Unknown action."]);}$a=$_GET["action"]??"";if($a==="stats")done(["users"=>(int)$pdo->query("SELECT COUNT(*) FROM users")->fetchColumn(),"jobs"=>(int)$pdo->query("SELECT COUNT(*) FROM jobs")->fetchColumn(),"apps"=>(int)$pdo->query("SELECT COUNT(*) FROM applications")->fetchColumn()]);if($a==="jobs")done($pdo->query("SELECT * FROM jobs ORDER BY posted_at DESC")->fetchAll());if($a==="users")done($pdo->query("SELECT id,name,email,role,created_at FROM users ORDER BY created_at DESC")->fetchAll());done(["success"=>false,"message"=>"Unknown action."]);?>